// import React from "react";

function RatingStars({ value = 0, onChange = () => {}, max = 5 }) {
  const buttons = [];
  for (let i = 1; i <= max; i++) {
    buttons.push(
      <button key={i} type="button" onClick={() => onChange(i)}>
        {i <= value ? "*" : "-"}
      </button>
    );
  }

  return <div className="stars">{buttons}</div>;
}


export default RatingStars;
